package com.aoo.bcg.common.concurrency;import static org.junit.jupiter.api.Assertions.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class ContentionRetryExecutorTest{@Test void retriesOnlyClassifiedContentionAndStopsAtCatalogLimit()throws Exception{var executor=new ContentionRetryExecutor();var calls=new AtomicInteger();assertEquals("ok",executor.execute("txn-1",()->{if(calls.incrementAndGet()<3)throw new java.sql.SQLTransactionRollbackException("deadlock");return"ok";},ContentionRetryExecutor::standardContention));assertEquals(3,calls.get());calls.set(0);assertThrows(IllegalArgumentException.class,()->executor.execute("txn-2",()->{calls.incrementAndGet();throw new IllegalArgumentException("invalid");},ContentionRetryExecutor::standardContention));assertEquals(1,calls.get());}}
